-- Regenerated by hand from the production database, 2026-08-14.
-- Not produced by a migration tool. See NOTES.md.

CREATE TABLE merchants (
    id            SERIAL,
    name          VARCHAR(255),
    contact_email VARCHAR(255),
    country       VARCHAR(2),
    active        VARCHAR(5),
    created_at    TIMESTAMP
);

CREATE TABLE customers (
    id            SERIAL,
    email         VARCHAR(255),
    full_name     VARCHAR(255),
    date_of_birth VARCHAR(20),
    card_last4    CHAR(4),
    card_pan      TEXT,
    notes         TEXT,
    support_notes TEXT,
    risk_comments TEXT,
    deleted       INT,
    created_at    TIMESTAMP
);

CREATE TABLE transactions (
    id             SERIAL,
    merchant_id    INT,
    customer_id    INT,
    amount         FLOAT,
    currency       VARCHAR(3),
    status         VARCHAR(32),
    processor_ref  VARCHAR(64),
    merchant_name  VARCHAR(255),
    customer_email VARCHAR(255),
    created_at     TIMESTAMP
);

CREATE INDEX idx_transactions_created_at ON transactions (created_at);

CREATE TABLE transaction_events (
    id             SERIAL,
    transaction_id INT,
    event_type     VARCHAR(64),
    payload        TEXT,
    created_at     TIMESTAMP
);

CREATE TABLE settlements (
    id           SERIAL,
    merchant_id  INT,
    period_start TIMESTAMP,
    period_end   TIMESTAMP,
    gross_amount FLOAT,
    fee_amount   FLOAT,
    net_amount   FLOAT,
    currency     VARCHAR(3),
    created_at   TIMESTAMP
);

CREATE TABLE payouts (
    id            SERIAL,
    settlement_id INT,
    amount        FLOAT,
    currency      VARCHAR(3),
    status        VARCHAR(32),
    sent_at       TIMESTAMP
);
